import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.B7PviQjB.js";const i="/docs/images/docs-editor/find-and-spelling-replace.png",s="/docs/images/docs-editor/find-and-spelling-suggestions.png",m=JSON.parse('{"title":"Find text and check spelling","description":"Find and replace text in a doc and fix misspelled words from the right-click menu.","frontmatter":{"title":"Find text and check spelling","description":"Find and replace text in a doc and fix misspelled words from the right-click menu.","type":"how-to"},"headers":[],"relativePath":"docs-editor/find-and-spelling.md","filePath":"docs-editor/find-and-spelling.md"}'),r={name:"docs-editor/find-and-spelling.md"};function l(d,e,c,h,p,g){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="find-text-and-check-spelling" tabindex="-1">Find text and check spelling <a class="header-anchor" href="#find-text-and-check-spelling" aria-label="Permalink to &quot;Find text and check spelling&quot;">​</a></h1><p>Search a doc for words or patterns, replace them, and fix misspellings.</p><h2 id="find-text" tabindex="-1">Find text <a class="header-anchor" href="#find-text" aria-label="Permalink to &quot;Find text&quot;">​</a></h2><ol><li>Press <code>⌘+F</code> / <code>Ctrl+F</code>. The find bar opens.</li><li>Type what you&#39;re looking for. Every match is highlighted, and the bar shows the count, such as <strong>2 of 7</strong>, or <strong>No results</strong>.</li><li>Press <code>Enter</code> for the next match and <code>Shift+Enter</code> for the previous one, or click the arrows.</li><li>Press <code>Escape</code>, or click the close button at the end of the bar, to close it.</li></ol><p>To narrow the search, turn on <strong>Match case</strong>, or <strong>Use regex</strong> to search with a regular expression such as <code>20\\d\\d</code>.</p><h2 id="replace-text" tabindex="-1">Replace text <a class="header-anchor" href="#replace-text" aria-label="Permalink to &quot;Replace text&quot;">​</a></h2><ol><li>Press <code>⌘+H</code> / <code>Ctrl+H</code>. The find bar opens with a <strong>Replace</strong> row.</li><li>Type the text to find, then the replacement.</li><li>Click <strong>Replace</strong> to change the current match, or <strong>All</strong> to change every match.</li></ol><p>People with view-only access can search but don&#39;t see the replace row.</p><p><img src="'+i+'" alt="Find bar with a replace row and highlighted matches in the document"></p><h2 id="fix-a-misspelled-word" tabindex="-1">Fix a misspelled word <a class="header-anchor" href="#fix-a-misspelled-word" aria-label="Permalink to &quot;Fix a misspelled word&quot;">​</a></h2><p>Misspelled words get a red wavy underline as you type.</p><ol><li>Right-click the underlined word.</li><li>Select a suggestion at the top of the menu.</li></ol><p>The word is replaced, and you can undo it like any edit. While suggestions load, the menu shows <strong>Checking…</strong>; if there are none, it shows <strong>No suggestions</strong>.</p><p><img src="'+s+'" alt="Right-click menu over a misspelled word with spelling suggestions above Paste and Add link"></p><h2 id="use-the-right-click-menu" tabindex="-1">Use the right-click menu <a class="header-anchor" href="#use-the-right-click-menu" aria-label="Permalink to &quot;Use the right-click menu&quot;">​</a></h2><p>Right-click in the text to see the actions that apply where you clicked:</p><ul><li>Spelling suggestions, on an underlined word</li><li><strong>Cut</strong> and <strong>Copy</strong>, when text is selected, and <strong>Paste</strong></li><li><strong>Add link</strong></li><li><strong>Insert comment</strong>, when text is selected and you&#39;re signed in</li></ul><p>Right-clicking in a table opens the table menu instead. See <a href="/docs/docs-editor/tables.html">Tables</a>.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>Find and replace open only from the keyboard shortcuts, so they need a hardware keyboard. Misspelled words are still underlined.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Spell check is always on and can&#39;t be turned off.</li><li>Words in Latin letters are checked against an English dictionary, so French or German words may be marked. Words in other scripts, such as Korean, are never marked.</li><li>Words in tables, headers, and footers aren&#39;t checked.</li><li>With view-only access, the right-click menu shows no spelling suggestions.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/collaborate/comments.html">Comments</a> to discuss a passage instead of changing it.</li><li><a href="/docs/docs-editor/keyboard-shortcuts.html">Keyboard shortcuts</a> for find and replace shortcuts.</li><li><a href="/docs/docs-editor/format-text.html">Format text</a> to add a link from the right-click menu.</li></ul>',24)])])}const f=t(r,[["render",l]]);export{m as __pageData,f as default};
